def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objs = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p = (y+dy, x+dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p)
                        stack.append(p)
            minr = min(y for y,x in cells)
            minc = min(x for y,x in cells)
            shape = [(y-minr, x-minc) for y,x in cells]
            objs.append((minr, minc, color, shape))
    objs.sort(key=lambda o: (o[1], o[0]))
    out = [[0]*w for _ in range(h)]
    top = left = 0
    for i, (_, _, color, shape) in enumerate(objs):
        if i:
            prev = objs[i-1][3]
            top += max(y for y,x in prev)
            left += max(x for y,x in prev)
        for y,x in shape:
            if top+y < h and left+x < w:
                out[top+y][left+x] = color
    return out
